\\\s*$/.test(String(v));\\nconst parseReq = (r) =&gt; {\\n  if (r == null || r === \\&quot;\\&quot;) return [];\\n  if (Array.isArray(r) &amp;&amp; r.length &amp;&amp; r.every(isNum)) return r.map((v, idx) =&gt; ({ idx, val: num(v) })).filter((q) =&gt; q.val &gt; 0);\\n  const pairs = [];\\n  for (const e of [r].flat(Infinity)) {\\n    if (e &amp;&amp; typeof e === \\&quot;object\\&quot;) {\\n      if (\\&quot;name\\&quot; in e) pairs.push([e.name, e.desc]);\\n      else pairs.push(...Object.entries(e));\\n    } else for (const s of String(e).split(\\&quot;,\\&quot;)) {\\n      const m = s.match(/([^\\\\d:+-]+?)\\\\s*[:=]?\\\\s*(\\\\d+)/) ?? s.match(/(\\\\d+)\\\\s*(.+)/)?.slice(0).reverse();\\n      if (m) pairs.push(/^\\\\d/.test(m[1]) ? [m[2], m[1]] : [m[1], m[2]]);\\n    }\\n  }\\n  return pairs.map(([n, v]) =&gt; ({ idx: statIdx(n), val: num(v), n: String(n).trim() }));\\n};\\n\\n// \\&quot;body\\&quot;/\\&quot;shield\\&quot; : \\&quot;+5 AC\\&quot; / \\&quot;+Force AC\\&quot; / \\&quot;+Force(...) AC\\&quot; dans enchant -&gt; ac ; modificateur = (stat - 10) / 2 arrondi bas, x2 si (...) (minimum 0)\\nconst acOf = (d, st, warn) =&gt; {\\n  if (![\\&quot;body\\&quot;, \\&quot;shield\\&quot;].includes(String(d.category ?? \\&quot;\\&quot;).toLowerCase())) return d.ac;\\n  const descs = [d.enchant ?? []].flat(Infinity).map((e) =&gt; (e &amp;&amp; typeof e === \\&quot;object\\&quot; ? e.desc ?? \\&quot;\\&quot; : e)).join(\\&quot;\\\\n\\&quot;);\\n  let found = false, total = 0;\\n  // \\&quot;xx AC\\&quot; dans material.desc : ajouté tel quel\\n  const mat = [d.material ?? []].flat(Infinity).map((e) =&gt; (e &amp;&amp; typeof e === \\&quot;object\\&quot; ? e.desc ?? \\&quot;\\&quot; : e)).join(\\&quot;\\\\n\\&quot;);\\n  for (const m of String(mat).matchAll(/([+-]?)\\\\s*(\\\\d+(?:\\\\.\\\\d+)?)\\\\s*AC\\\\b/gi)) { found = true; total += (m[1] === \\&quot;-\\&quot; ? -1 : 1) * parseFloat(m[2]); }\\n  for (const m of String(descs).matchAll(/([+-])\\\\s*([\\\\p{L}\\\\d.]+?)\\\\s*(\\\\([^)]*\\\\))?\\\\s*AC\\\\b/giu)) {\\n    let v;\\n    if (/^\\\\d+(\\\\.\\\\d+)?$/.test(m[2])) v = parseFloat(m[2]);\\n    else {\\n      const k = statIdx(m[2]);\\n      if (k &lt; 0) { warn?.(`stat inconnue dans enchant (${m[2]})`); continue; }\\n      const mod = Math.floor((num(st[k]) - 10) / 2);\\n      v = m[3] ? Math.max(0, mod * 2) : mod; // (...) : x2, jamais négatif\\n    }\\n    found = true;\\n    total += m[1] === \\&quot;-\\&quot; ? -v : v;\\n  }\\n  // \\&quot;ac\\&quot; seulement si aucune valeur AC dans material / enchant\\n  return found ? total : d.ac;\\n};\\n\\n// Équipement : \\&quot;Objet\\&quot; (même note) ou [[Note]] / [[Note#Objet]] (autre note)\\nconst here = app.workspace.getActiveFile();\\nlet links = [monster.equipment ?? []].flat(Infinity).filter((l) =&gt; l);\\n// Sans \\&quot;equipment:\\&quot;, prend tous les statblocks d'équipement de la note (ceux avec category ou layout Equipment)\\nif (!links.length) links = blocksOf(here)\\n  .filter((d) =&gt; d.name != null &amp;&amp; String(d.name) !== String(monster.name) &amp;&amp; (d.category != null || /equipment/i.test(String(d.layout ?? \\&quot;\\&quot;))))\\n  .map((d) =&gt; String(d.name));\\nconst sel = monster.equipped == null ? null : [monster.equipped].flat(Infinity).filter((l) =&gt; l).map((l) =&gt; clean(l).toLowerCase());\\nconst items = [], warnings = [];\\nfor (const raw of links) {\\n  const key = clean(raw);\\n  const [note, sub] = key.includes(\\&quot;#\\&quot;) ? key.split(\\&quot;#\\&quot;) : [key, null];\\n  const name = (sub ?? note).trim();\\n  const file = note ? app.metadataCache.getFirstLinkpathDest(note.trim(), here?.path ?? \\&quot;\\&quot;) : here;\\n  let data = file &amp;&amp; !sub ? app.metadataCache.getFileCache(file)?.frontmatter : null;\\n  if (!data?.category) {\\n    const pool = blocksOf(file ?? here);\\n    data = pool.find((d) =&gt; String(d.name ?? \\&quot;\\&quot;).trim().toLowerCase() === name.toLowerCase()) ?? (file &amp;&amp; !sub ? pool.find((d) =&gt; d.category) : null);\\n  }\\n  data ??= window.FantasyStatblocks?.getCreatureFromBestiary?.(name);\\n  if (!data) { warnings.push(`Introuvable : ${name}`); continue; }\\n  data = { ...data, damage: dmgOf(data, stats) };\\n  data.ac = acOf(data, stats, (w) =&gt; warnings.push(`${data.name ?? name} : ${w}`));\\n  const wanted = sel ? sel.includes(key.toLowerCase()) : true;\\n  const reqs = parseReq(data.require);\\n  for (const q of reqs) if (q.idx &lt; 0) warnings.push(`${data.name ?? name} : stat inconnue dans require (${q.n})`);\\n  // Prérequis non atteints -&gt; objet inutilisable\\n  const unmet = reqs.filter((q) =&gt; q.idx &gt;= 0 &amp;&amp; num(stats[q.idx]) &lt; q.val).map((q) =&gt; `${STATS[q.idx]} ${q.val} (${num(stats[q.idx])})`);\\n  items.push({ key, name: data.name ?? name, file: file &amp;&amp; file !== here ? file : null, data, wanted, unmet, on: wanted &amp;&amp; !unmet.length, cat: String(data.category ?? \\&quot;\\&quot;).toLowerCase() });\\n}\\n\\n// Règles d'emplacement, sur les objets cochés uniquement\\nconst active = items.filter((i) =&gt; i.on);\\nconst body = active.filter((i) =&gt; i.cat === \\&quot;body\\&quot;), shield = active.filter((i) =&gt; i.cat === \\&quot;shield\\&quot;), cape = active.filter((i) =&gt; i.cat === \\&quot;cape\\&quot;);\\nconst hands = active.reduce((s, i) =&gt; s + ({ \\&quot;1h\\&quot;: 1, shield: 1, \\&quot;2h\\&quot;: 2 }[i.cat] ?? 0), 0);\\nif (body.length &gt; 1) warnings.push(`${body.length} \\&quot;body\\&quot; cochés (max 1)`);\\nif (shield.length &gt; 1) warnings.push(`${shield.length} \\&quot;shield\\&quot; cochés (max 1)`);\\nif (cape.length &gt; 1) warnings.push(`${cape.length} \\&quot;cape\\&quot; cochées (max 1)`);\\nif (hands &gt; 2) warnings.push(`Mains occupées : ${hands}/2`);\\nfor (const i of items) if (![\\&quot;body\\&quot;, \\&quot;cape\\&quot;, \\&quot;shield\\&quot;, \\&quot;1h\\&quot;, \\&quot;2h\\&quot;].includes(i.cat)) warnings.push(`${i.name} : category invalide (body / cape / shield / 1H / 2H)`);\\n\\n// AC = body + shield additionnés (\\&quot;10 +50\\&quot; et \\&quot;-3 +30\\&quot; -&gt; \\&quot;7 +80\\&quot;) ; vitesse = 1er nombre\\nconst speedBefore = monster.speed;\\nconst parts = [body[0], shield[0]].filter((i) =&gt; i &amp;&amp; i.data.ac != null);\\nif (parts.length) {\\n  const acSum = parts.reduce((s, i) =&gt; s + num(i.data.ac), 0), dmgSum = parts.reduce((s, i) =&gt; s + num(i.data.damage), 0);\\n  monster.ac = `${acSum}${dmgSum ? ` ${dmgSum &gt; 0 ? \\&quot;+\\&quot; : \\&quot;-\\&quot;}${Math.abs(dmgSum)}` : \\&quot;\\&quot;}`;\\n  monster.speed = String(acSum);\\n}\\n// Retire les lettres de l'AC du joueur\\nif (monster.ac != null) monster.ac = String(monster.ac).replace(/[a-zA-ZÀ-ÿ]/g, \\&quot;\\&quot;).replace(/\\\\s+/g, \\&quot; \\&quot;).replace(/\\\\(\\\\s+/g, \\&quot;(\\&quot;).replace(/\\\\s+\\\\)/g, \\&quot;)\\&quot;).replace(/\\\\(\\\\)/g, \\&quot;\\&quot;).trim();\\n// Résistances des objets cochés, regroupées par nom, valeurs jointes par \\&quot;, \\&quot; (sans doublons)\\nconst groups = new Map();\\nfor (const r of active.flatMap((i) =&gt; [i.data.resistances ?? []].flat(Infinity))) {\\n  const obj = r &amp;&amp; typeof r === \\&quot;object\\&quot;;\\n  const name = String(obj ? r.name ?? \\&quot;Résistances\\&quot; : \\&quot;Résistances\\&quot;).trim();\\n  const k = name.toLowerCase();\\n  if (!groups.has(k)) groups.set(k, { name, vals: [] });\\n  const g = groups.get(k);\\n  for (const v of String(obj ? r.desc ?? \\&quot;\\&quot; : r ?? \\&quot;\\&quot;).split(\\&quot;,\\&quot;).map((x) =&gt; x.trim()))\\n    if (v &amp;&amp; !g.vals.some((x) =&gt; x.toLowerCase() === v.toLowerCase())) g.vals.push(v);\\n}\\nif (groups.size) monster.resistances = [...groups.values()].map((g) =&gt; ({ name: g.name, desc: g.vals.join(\\&quot;, \\&quot;) }));\\n\\n// Écrit \\&quot;clé: valeur\\&quot; dans le bloc du joueur (remplace la ligne existante)\\nconst writeKey = async (key, val) =&gt; {\\n  if (!here) return;\\n  const txt = await app.vault.process(here, (t) =&gt; {\\n    for (const m of t.matchAll(FENCE)) {\\n      let d; try { d = parseYaml(m[3]); } catch (e) { continue; }\\n      if (!(d?.equipment || d?.stats || d?.lvl != null) || d?.category != null || String(d.name) !== String(monster.name)) continue;\\n      let inner = m[3].replace(new RegExp(`^${key}:.*(\\\\\\\\n|$)`, \\&quot;m\\&quot;), \\&quot;\\&quot;);\\n      if (!inner.endsWith(\\&quot;\\\\n\\&quot;)) inner += \\&quot;\\\\n\\&quot;;\\n      inner += `${key}: ${val}\\\\n`;\\n      return t.slice(0, m.index) + m[1] + m[2] + inner + m[1] + t.slice(m.index + m[0].length);\\n    }\\n    return t;\\n  });\\n  cache[here.path] = txt;\\n};\\nconst save = (keys) =&gt; writeKey(\\&quot;equipped\\&quot;, JSON.stringify(keys));\\n// Enregistre la vitesse dans la note seulement si elle a changé (évite les boucles)\\nif (parts.length &amp;&amp; String(speedBefore ?? \\&quot;\\&quot;) !== monster.speed) writeKey(\\&quot;speed\\&quot;, monster.speed);\\nmonster._equip = { items, warnings, hands, save };&quot;},{&quot;type&quot;:&quot;inline&quot;,&quot;id&quot;:&quot;ebc91b5bbb68&quot;,&quot;properties&quot;:[],&quot;hasRule&quot;:true,&quot;nested&quot;:[{&quot;type&quot;:&quot;group&quot;,&quot;id&quot;:&quot;2b689ad94a7b&quot;,&quot;properties&quot;:[&quot;name&quot;,&quot;size&quot;,&quot;type&quot;,&quot;subtype&quot;,&quot;alignment&quot;],&quot;nested&quot;:[{&quot;type&quot;:&quot;inline&quot;,&quot;id&quot;:&quot;8aca599b99ca&quot;,&quot;properties&quot;:[],&quot;hasRule&quot;:false,&quot;nested&quot;:[{&quot;type&quot;:&quot;heading&quot;,&quot;id&quot;:&quot;3b0b7968792a&quot;,&quot;properties&quot;:[&quot;name&quot;],&quot;conditioned&quot;:true,&quot;size&quot;:1}]},{&quot;type&quot;:&quot;subheading&quot;,&quot;id&quot;:&quot;ea281a69faf9&quot;,&quot;properties&quot;:[&quot;race&quot;,&quot;size&quot;],&quot;conditioned&quot;:true,&quot;separator&quot;:&quot;, &quot;},{&quot;type&quot;:&quot;property&