class=\"statblock-item-container rule-container\"><div class=\"tapered-rule svelte-k72li0\"></div></div><div class=\"statblock-item-container text-container \"> <div class=\"line\"><div class=\"statblock-markdown svelte-1c3hzq4\"><p dir=\"auto\">Vous ne savez pas si vos mains sont froides à cause de la magie de glace, ou parce que vous fistez les restes d'un corps</p></div></div></div></details></div></div></div></div> <div class=\"bar svelte-zyyfbl\"></div></div> </div></div>\n<div class=\"block-language-statblock statblock-plugin-container\" data-live-statblock=\"{&quot;path&quot;:&quot;Jeu/Sessions du Masque/Joueurs/Léoric.md&quot;,&quot;index&quot;:3,&quot;layout&quot;:[{&quot;type&quot;:&quot;javascript&quot;,&quot;id&quot;:&quot;ac0c0de00001&quot;,&quot;code&quot;:&quot;const app = property?.app ?? window.app;\\nconst num = (v) =&gt; (String(v ?? \\&quot;\\&quot;).match(/[+-]?\\\\s*\\\\d+(\\\\.\\\\d+)?/g) ?? []).reduce((s, x) =&gt; s + parseFloat(x.replace(/\\\\s/g, \\&quot;\\&quot;)), 0);\\nconst STATS = [\\&quot;Force\\&quot;, \\&quot;Dextérité\\&quot;, \\&quot;Mental\\&quot;, \\&quot;Perception\\&quot;, \\&quot;Charisme\\&quot;];\\nconst norm = (s) =&gt; String(s).normalize(\\&quot;NFD\\&quot;).replace(/[\\\\u0300-\\\\u036f]/g, \\&quot;\\&quot;).toLowerCase().trim();\\nconst statIdx = (n) =&gt; { const x = norm(n); return STATS.findIndex((h) =&gt; norm(h) === x || (x.length &gt;= 3 &amp;&amp; norm(h).startsWith(x))); };\\n// Mini parseur YAML (clés, listes, listes d'objets, [inline], |, &gt;)\\nconst miniYaml = (src) =&gt; {\\n  const L = src.replace(/\\\\r/g, \\&quot;\\&quot;).replace(/\\\\t/g, \\&quot;  \\&quot;).split(\\&quot;\\\\n\\&quot;)\\n    .filter((l) =&gt; l.trim() &amp;&amp; !/^\\\\s*#/.test(l)).map((l) =&gt; ({ ind: l.search(/\\\\S/), t: l.trim() }));\\n  const isItem = (t) =&gt; t === \\&quot;-\\&quot; || t.startsWith(\\&quot;- \\&quot;);\\n  const scal = (s) =&gt; {\\n    s = s.trim();\\n    if (/^([\\&quot;']).*\\\\1$/.test(s)) return s.slice(1, -1);\\n    s = s.replace(/\\\\s+#.*$/, \\&quot;\\&quot;);\\n    if (/^\\\\[.*\\\\]$/.test(s)) return s.slice(1, -1).split(\\&quot;,\\&quot;).filter((x) =&gt; x.trim()).map(scal);\\n    if (s === \\&quot;\\&quot; || s === \\&quot;null\\&quot; || s === \\&quot;~\\&quot;) return null;\\n    if (/^-?\\\\d+(\\\\.\\\\d+)?$/.test(s)) return +s;\\n    if (s === \\&quot;true\\&quot; || s === \\&quot;false\\&quot;) return s === \\&quot;true\\&quot;;\\n    return s;\\n  };\\n  const block = (i, ind) =&gt; isItem(L[i].t) ? list(i, ind) : map(i, ind);\\n  const list = (i, ind) =&gt; {\\n    const arr = [];\\n    while (i &lt; L.length &amp;&amp; L[i].ind === ind &amp;&amp; isItem(L[i].t)) {\\n      const rest = L[i].t.slice(1).trim();\\n      if (!rest) { if (i + 1 &lt; L.length &amp;&amp; L[i + 1].ind &gt; ind) { const [v, j] = block(i + 1, L[i + 1].ind); arr.push(v); i = j; } else { arr.push(null); i++; } }\\n      else if (/^[^\\&quot;'\\\\[{][^:]*:(\\\\s|$)/.test(rest)) { L[i] = { ind: ind + L[i].t.indexOf(rest), t: rest }; const [v, j] = map(i, L[i].ind); arr.push(v); i = j; }\\n      else { arr.push(scal(rest)); i++; }\\n    }\\n    return [arr, i];\\n  };\\n  const map = (i, ind) =&gt; {\\n    const o = {};\\n    while (i &lt; L.length &amp;&amp; L[i].ind === ind &amp;&amp; !isItem(L[i].t)) {\\n      const m = L[i].t.match(/^(\\&quot;[^\\&quot;]*\\&quot;|'[^']*'|[^:]+?):(?:\\\\s+(.*))?$/);\\n      i++;\\n      if (!m) continue;\\n      const k = m[1].replace(/^[\\&quot;']|[\\&quot;']$/g, \\&quot;\\&quot;), v = (m[2] ?? \\&quot;\\&quot;).trim();\\n      if (/^[|&gt;][-+]?$/.test(v)) { const b = []; while (i &lt; L.length &amp;&amp; L[i].ind &gt; ind) b.push(L[i++].t); o[k] = b.join(v[0] === \\&quot;|\\&quot; ? \\&quot;\\\\n\\&quot; : \\&quot; \\&quot;); }\\n      else if (v === \\&quot;\\&quot; &amp;&amp; i &lt; L.length &amp;&amp; (L[i].ind &gt; ind || (L[i].ind === ind &amp;&amp; isItem(L[i].t)))) { const [val, j] = block(i, L[i].ind); o[k] = val; i = j; }\\n      else o[k] = scal(v);\\n    }\\n    return [o, i];\\n  };\\n  return L.length ? block(0, L[0].ind)[0] : null;\\n};\\nlet parseYaml = miniYaml;\\ntry { parseYaml = window.require(\\&quot;obsidian\\&quot;).parseYaml ?? miniYaml; } catch (e) {}\\n// Lecture synchrone d'une note (desktop) ; sur mobile, cache rempli au 1er rendu\\nconst cache = (window.__aerethiosCache ??= {});\\nconst read = (f) =&gt; {\\n  const fs = window.require?.(\\&quot;fs\\&quot;);\\n  if (fs &amp;&amp; app.vault.adapter.getFullPath) return fs.readFileSync(app.vault.adapter.getFullPath(f.path), \\&quot;utf8\\&quot;);\\n  app.vault.cachedRead(f).then((t) =&gt; (cache[f.path] = t));\\n  return cache[f.path] ?? \\&quot;\\&quot;;\\n};\\nconst FENCE = /^(```+|~~~+)(\\\\s*statblock[^\\\\n]*\\\\n)([\\\\s\\\\S]*?)^\\\\1/gm;\\nconst blocksOf = (f) =&gt; {\\n  if (!f) return [];\\n  const out = [];\\n  for (const m of read(f).matchAll(FENCE)) { try { const d = parseYaml(m[3]); if (d) out.push(d); } catch (e) {} }\\n  return out;\\n};\\n// \\&quot;body\\&quot;/\\&quot;shield\\&quot; : \\&quot;+5 AC\\&quot; / \\&quot;+Force AC\\&quot; / \\&quot;+Force(...) AC\\&quot; dans enchant -&gt; ac ; modificateur = (stat - 10) / 2 arrondi bas, x2 si (...) (minimum 0)\\nconst acOf = (d, st, warn) =&gt; {\\n  if (![\\&quot;body\\&quot;, \\&quot;shield\\&quot;].includes(String(d.category ?? \\&quot;\\&quot;).toLowerCase())) return d.ac;\\n  const descs = [d.enchant ?? []].flat(Infinity).map((e) =&gt; (e &amp;&amp; typeof e === \\&quot;object\\&quot; ? e.desc ?? \\&quot;\\&quot; : e)).join(\\&quot;\\\\n\\&quot;);\\n  let found = false, total = 0;\\n  // \\&quot;xx AC\\&quot; dans material.desc : ajouté tel quel\\n  const mat = [d.material ?? []].flat(Infinity).map((e) =&gt; (e &amp;&amp; typeof e === \\&quot;object\\&quot; ? e.desc ?? \\&quot;\\&quot; : e)).join(\\&quot;\\\\n\\&quot;);\\n  for (const m of String(mat).matchAll(/([+-]?)\\\\s*(\\\\d+(?:\\\\.\\\\d+)?)\\\\s*AC\\\\b/gi)) { found = true; total += (m[1] === \\&quot